//! Safe Rust wrappers over libgit2's public API.
//!
//! The tree mirrors `crustify/artifacts/modules.json`: one module per link unit, and
//! within it one module per translation unit, at the TU's path below the C root
//! (`libgit2_crustify::libgit2::src::libgit2::repository` for `src/libgit2/repository.c`),
//! holding the items of the TU and of the headers bundled with it. The raw bindings are the
//! public [`sys`] module, one module per link unit, through which the C that is not wrapped
//! yet is reached.

pub mod sys;

#[cfg(feature = "libgit2")]
pub mod libgit2;

#[cfg(feature = "git2")]
pub mod git2;
src/git2:
src
src.rs

src/git2/src:
cli
cli.rs

src/git2/src/cli:
opt.rs
//! `src/cli/opt.c`: the command-line argument parser of the `git2` CLI (`src/cli/opt.h`),
//! ported to Rust.
allowlist.txt
bindings.rs
external.txt
shims.c
shims.h
static_fns.c
wrapper.h
//! The raw bindings: one public module per link unit, generated by bindgen from the C under
//! `c/` and its `sys/<link-unit>/` input, as crustify's `bindgen` skill lays them out.
//!
//! Each module holds the committed `sys/<link-unit>/bindings.rs`, or the bindings the
//! `bindgen` feature regenerates into `OUT_DIR`. Only the items the link unit's
//! `allowlist.txt` names are generated, under their C names; callable macro shims from its
//! `shims.c` are bound as `crustify_<NAME>`. The C that is not translated yet is reached
//! through them.

#[cfg(not(all(target_arch = "x86_64", target_os = "linux", target_env = "gnu")))]
compile_error!(
    "the raw bindings are generated for x86_64-unknown-linux-gnu, the only target the crate \
     supports"
);

/// Raw bindings to libgit2's public API (`include/git2.h` and `include/git2/sys/*.h`, built
/// with `GIT_DEPRECATE_HARD`) and to the internal items its batches bind, the `libgit2` link
/// unit (`libgit2.so`).
#[expect(
    clippy::allow_attributes,
    reason = "bindgen's output follows C's names and shapes, so the generated module is exempt \
              from the workspace's lints"
)]
#[allow(
    nonstandard_style,
    unsafe_op_in_unsafe_fn,
    missing_docs,
    rust_2018_idioms,
    unreachable_pub,
    unused_qualifications,
    unused_lifetimes,
    let_underscore_drop,
    trivial_casts,
    trivial_numeric_casts,
    dead_code,
    unused_imports,
    clippy::correctness,
    clippy::all,
    clippy::pedantic,
    clippy::cargo,

