//! values, which the CLI's remaining C relies on. None reaches C, so Miri runs them all.

use libgit2_crustify::git2::src::cli::opt::{Kind, ParseFlags, Status, Usage};

/// Every usage flag a constant names, `DEFAULT` aside.
const USAGE_FLAGS: [Usage; 6] = [
